import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Real MySQL; scoped two-person fixtures roll back. No actual WeChat login or model billing. */
public class MiniappAgentChecks {
    static int checks;
    static void check(String label,boolean b){if(!b)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
    static void reject(String label,int status,Runnable call){try{call.run();throw new AssertionError(label);}catch(EhrException e){check(label,e.status==status);}}
    static class Settings extends HealthAgentSettings{Settings(){super(new ModelRecognitionSettings());}Map<String,Object> status(){return map("enabled",true);}Map<String,Object> validated(){return map("enabled",true,"apiKey","synthetic-only","baseUrl","https://example.test/v1","model","fixture");}}
    static class Client extends HealthAgentClient {
        int calls;boolean fail,revoke;EhrRepository db;String binding;
        Client(EhrRepository db){super(new Settings());this.db=db;}
        public Map<String,Object> respond(List<Object> input,List<Object> tools,String rules,long deadline){calls++;if(fail)throw new EhrException(504,"测试超时");if(revoke)db.exec("UPDATE a_miniapp_employee_bindings SET binding_status='revoked' WHERE binding_id=?",binding);
            if(calls%2==1)return map("output",Arrays.asList(map("type","function_call","name","get_my_profile","call_id","my_profile","arguments","{}")));
            check("personal_tool_output_round_trip",input.stream().anyMatch(x->x instanceof Map&&"function_call_output".equals(((Map<?,?>)x).get("type"))));
            return map("output",Arrays.asList(map("type","message","content",Arrays.asList(map("type","output_text","text","已读取你本人的职业健康背景，仅供健康沟通参考。")))));
        }
    }
    static String user(EhrRepository db){String user=id();db.insert("a_miniapp_users",map("mini_user_id",user,"data_mode","synthetic","app_id","wx0000000000000000","open_id","agent-fixture-"+user,"consent_version","test","consent_at",now(),"created_at",now(),"last_login_at",now()));return user;}
    static void bind(MiniappIdentityService identity,EhrActor doctor,String user,String record,String name,String code){Map<String,Object> issued=identity.issue(doctor,record,map("requestKey",id()));check("fixture_identity_matches_issued_roster",name.equals(issued.get("name"))&&code.equals(issued.get("employeeNo")));Map<String,Object> verified=identity.verify(map("mini_user_id",user),map("name",name,"employeeNo",code,"verificationCode",issued.get("verificationCode")));identity.confirm(map("mini_user_id",user),map("confirmed",true,"confirmationToken",verified.get("confirmationToken")));}
    static String report(EhrRepository db,EhrService ehr,EhrActor doctor,String record,boolean approve){String rid=HealthAgentChecks.report(db,ehr,doctor,record);db.insert("a_extraction_jobs",ehr.scoped(doctor,"job_id",id(),"report_id",rid,"revision",1,"request_key",id(),"pipeline_version","mini-agent-fixture","status","uploaded"));if(approve){Map<String,Object> r=ehr.report(doctor,rid,1,false);ehr.saveDraft(doctor,rid,1,map("fullName",ehr.profile(doctor,record,false).get("employee_name"),"examDate","2026-11-15","institution","合成测试体检机构","formalConclusion","合成报告：血糖项目需关注","items",Arrays.asList(map("name","测试血糖","value","8.2","unit","mmol/L","referenceRange","3.9-6.1","abnormal","H","page",1))),str(r.get("etag")));ehr.transition(doctor,rid,1,map("action","submit","requestKey",id(),"note","测试"));r=ehr.report(doctor,rid,1,false);ehr.transition(doctor,rid,1,map("action","approve","requestKey",id(),"note","测试","identityVerified",true,"etag",r.get("etag")));}return rid;}
    @SuppressWarnings("unchecked") public static void main(String[] args){DriverManagerDataSource ds=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(ds);EhrService ehr=new EhrService(db);HealthAgentStore admin=new HealthAgentStore(db,ehr);MiniappAgentStore store=new MiniappAgentStore(db,ehr);MiniappAgentTools tools=new MiniappAgentTools(store,db,ehr);Client client=new Client(db);MiniappAgentService service=new MiniappAgentService(store,tools,client,admin,ehr);MiniappIdentityService identity=new MiniappIdentityService(db,ehr,new MiniappWechatClient(),new MiniappRateLimiter(db));identity.mode="synthetic";String run=id().substring(0,8);EhrActor doctor=new EhrActor("miniapp-agent-test","MINIA_"+run,"synthetic",true,false);
        new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(tx->{try{
            String ua=user(db),ub=user(db),unbound=user(db);String ca="MA_"+run,cb="MB_"+run;
            String ra=str(ehr.upsert(doctor,null,map("name","合成甲职工","code",ca,"sex","男","org","测试单位","team","甲班组","job","甲岗位")).get("id"));String rb=str(ehr.upsert(doctor,null,map("name","合成乙职工","code",cb,"sex","女","org","测试单位","team","乙班组","job","乙岗位")).get("id"));
            bind(identity,doctor,ua,ra,"合成甲职工",ca);bind(identity,doctor,ub,rb,"合成乙职工",cb);MiniappAgentStore.Person a=store.person(ua,"synthetic"),b=store.person(ub,"synthetic");
            reject("unbound_cannot_use_agent",403,()->store.person(unbound,"synthetic"));reject("real_mode_cannot_read_synthetic_binding",403,()->store.person(ua,"real"));
            String cid=str(store.create(a).get("id"));check("context_personal_not_enterprise",Boolean.TRUE.equals(service.context(a).get("personalOnly"))&&!service.context(a).containsKey("statistics"));check("six_personal_read_only_tools",tools.catalog().size()==6);
            reject("enterprise_tool_not_available",403,()->tools.execute(a,"get_health_statistics",map(),map(),new ArrayList<>()));reject("employee_delete_tool_not_available",403,()->tools.execute(a,"prepare_employee_delete",map(),map(),new ArrayList<>()));reject("record_identity_cannot_be_injected",422,()->tools.execute(a,"get_my_profile",map("record_id",rb),map(),new ArrayList<>()));
            reject("other_employee_cannot_read_conversation",404,()->store.detail(b,cid,1,10));reject("other_employee_cannot_delete_conversation",404,()->store.delete(b,cid));reject("admin_cannot_read_personal_conversation",404,()->admin.detail(a.actor,cid));
            String ad=str(admin.create(doctor).get("id"));reject("personal_cannot_read_admin_conversation",404,()->store.detail(a,ad,1,10));check("admin_list_excludes_personal",((List<?>)admin.list(a.actor)).isEmpty());
            String ar=report(db,ehr,doctor,ra,true),candidate=report(db,ehr,doctor,ra,false),br=report(db,ehr,doctor,rb,true);
            List<Object> sources=new ArrayList<>();Map<String,Object> own=(Map<String,Object>)tools.execute(a,"get_my_report",map("report_id",ar,"revision",1,"page",1),map(),sources);check("own_confirmed_report_readable",!Boolean.TRUE.equals(own.get("candidate"))&&!sources.isEmpty()&&str(((Map<?,?>)sources.get(0)).get("detailPath")).startsWith("/ehr/miniapp/reports/"));
            reject("other_employee_report_rejected",404,()->tools.execute(a,"get_my_report",map("report_id",br,"revision",1,"page",1),map(),new ArrayList<>()));reject("other_report_context_rejected",404,()->tools.context(a,map("reportId",br,"revision",1)));
            reject("candidate_requires_explicit_selection",403,()->tools.execute(a,"get_my_report",map("report_id",candidate,"revision",1,"page",1),map(),new ArrayList<>()));Map<String,Object> cand=(Map<String,Object>)tools.execute(a,"get_my_report",map("report_id",candidate,"revision",1,"page",1),map("reportId",candidate,"revision",1),new ArrayList<>());check("explicit_candidate_keeps_candidate_label",Boolean.TRUE.equals(cand.get("candidate")));
            Map<String,Object> abnormal=(Map<String,Object>)tools.execute(a,"get_my_abnormal_items",map("indicator","","page",1),map(),new ArrayList<>());check("abnormal_results_personal_only",((List<Map<String,Object>>)abnormal.get("items")).stream().allMatch(r->ar.equals(r.get("reportId"))));check("no_confirmed_risk_means_unknown","unknown".equals(((Map<?,?>)tools.execute(a,"get_my_confirmed_risks",map(),map(),new ArrayList<>())).get("riskLevel")));
            Map<String,Object> request=map("conversationId",cid,"requestId","mini_request_0001","message","查询我的职业背景");Map<String,Object> spoof=new LinkedHashMap<>(request);spoof.put("recordId",rb);reject("request_rejects_client_employee_id",422,()->service.submit(a,spoof));
            Map<String,Object> accepted=service.submit(a,request);String tid=str(accepted.get("messageId"));check("submit_returns_queued",accepted.get("status").equals("queued"));check("repeated_submit_same_message",tid.equals(service.submit(a,request).get("messageId")));request.put("message","different");reject("same_key_changed_question_denied",409,()->service.submit(a,request));request.put("message","查询我的职业背景");
            String c2=str(store.create(a).get("id"));reject("one_pending_question_per_user",409,()->service.submit(a,map("conversationId",c2,"requestId","mini_request_0002","message","我的报告")));reject("queued_conversation_cannot_delete",409,()->store.delete(a,cid));reject("other_user_cannot_poll_message",404,()->store.result(b,tid));
            Map<String,Object> job=store.claim("synthetic");check("claim_sets_running",tid.equals(job.get("turn_id"))&&"running".equals(store.result(a,tid).get("status")));service.process(job);check("function_loop_completed_and_persisted","completed".equals(store.result(a,tid).get("status"))&&client.calls==2);check("history_returns_question_and_answer",((List<?>)store.detail(a,cid,1,10).get("items")).size()==1);check("retry_does_not_call_model_again","completed".equals(service.submit(a,request).get("status"))&&client.calls==2);
            client.fail=true;Map<String,Object> failed=service.submit(a,map("conversationId",c2,"requestId","mini_request_0003","message","再解释一次"));service.process(store.claim("synthetic"));check("timeout_is_recoverable_failed_message","MODEL_TIMEOUT".equals(store.result(a,str(failed.get("messageId"))).get("errorCode")));client.fail=false;
            Map<String,Object> interrupted=service.submit(a,map("conversationId",c2,"requestId","mini_request_0004","message","测试中断"));Map<String,Object> late=store.claim("synthetic");db.exec("UPDATE a_agent_turns SET deadline_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE turn_id=?",interrupted.get("messageId"));store.expire("synthetic");check("expired_turn_not_replayed_automatically","failed".equals(store.result(a,str(interrupted.get("messageId"))).get("status")));check("late_worker_cannot_overwrite_result",!store.finish(a,late,map("status","completed","answer","late"),new ArrayList<>()));
            int quota=store.perDay;store.perDay=0;reject("daily_quota_enforced",429,()->service.submit(a,map("conversationId",c2,"requestId","mini_request_0005","message","测试额度")));store.perDay=quota;
            Map<String,Object> revoked=service.submit(a,map("conversationId",c2,"requestId","mini_request_0006","message","测试解绑"));client.calls=0;client.revoke=true;client.binding=a.binding;service.process(store.claim("synthetic"));reject("revoked_binding_cannot_read_old_answer",403,()->store.result(a,str(revoked.get("messageId"))));check("revocation_stops_partial_result",db.count("SELECT COUNT(*) FROM a_agent_turns WHERE turn_id=? AND turn_status='failed' AND transcript_json=JSON_ARRAY()",revoked.get("messageId"))==1);client.revoke=false;
            db.exec("UPDATE a_miniapp_employee_bindings SET binding_status='active' WHERE binding_id=?",a.binding);String oldBinding=a.binding;db.exec("UPDATE a_miniapp_employee_bindings SET binding_status='revoked' WHERE binding_id=?",oldBinding);bind(identity,doctor,ua,ra,"合成甲职工",ca);MiniappAgentStore.Person rebound=store.person(ua,"synthetic");reject("new_binding_cannot_read_previous_binding_chat",404,()->store.detail(rebound,cid,1,10));
            db.exec("UPDATE a_miniapp_employee_bindings SET binding_status='revoked' WHERE binding_id=?",rebound.binding);db.exec("UPDATE a_miniapp_employee_bindings SET binding_status='active' WHERE binding_id=?",oldBinding);
            store.delete(a,cid);check("deleting_chat_does_not_reset_quota",db.count("SELECT COUNT(*) FROM a_miniapp_rate_limits WHERE bucket_key=? AND attempt_count>0",digest(bytes("mini-agent:"+a.mode+":day:"+a.user)))==1);reject("deleted_message_no_longer_readable",404,()->store.result(a,tid));check("delete_chat_preserves_personal_reports",ehr.rawReport(a.actor,ar,1,false)!=null&&ehr.rawReport(b.actor,br,1,false)!=null);return null;
        }finally{tx.setRollbackOnly();}});
        check("isolated_fixtures_rolled_back",db.count("SELECT COUNT(*) FROM a_agent_conversations WHERE scope_code=?",doctor.scope)==0);System.out.println("PASS Personal agent checks: "+checks+"; database fixtures rolled back");
    }
}
